# ---------------------------------------------------------------------------
# kit_materials.py
# Purpose : Builds the kit's shader recipes (kit_recipes.py, generated by tools/shaders/shader_gen.py) as Unreal
#           materials: one Custom node holding the recipe's HLSL, a TextureCoordinate for uv, texture object
#           parameters MainTex / AuxTex and one parameter per recipe parameter (u_<name>).
# Usage   : from kit_shaders import kit_materials        (in editor Python, Content/Python is on sys.path)
#           kit_materials.build("flash", "/Game/KitShaders")   -> the material asset
#           make_materials.py builds them all; shader_check.py checks them (python tools/dev.py check / smoke)
# Notes   : Sprites and lighting are Unlit + Translucent (emissive = rgb, opacity = a), the others Unlit + Opaque.
#           The check builds two opaque variants of the same graph, one showing rgb and one alpha, because a
#           translucent draw onto a render target blends alpha in ways that hide the value the recipe returned.
#           Coordinates are the mesh's UVs (Unreal's UV origin is top-left, as the recipes' image space).
# Authored: Written with Claude (Opus 5.5, claude-opus-5-5)
# ---------------------------------------------------------------------------
import unreal

from kit_shaders.kit_recipes import RECIPES

MEL = unreal.MaterialEditingLibrary
TRANSLUCENT_GROUPS = ("sprite", "lighting")
NODE_X = -900                               # graph layout: parameters left of the Custom node
CUSTOM_X = -450


def _tools():
    return unreal.AssetToolsHelpers.get_asset_tools()


def import_texture(png_path, dest, name):
    """Import a PNG as a linear, point-filtered, uncompressed, mip-less texture (pixel art and data maps)."""
    task = unreal.AssetImportTask()
    for key, value in (("filename", png_path), ("destination_path", dest), ("destination_name", name),
                       ("automated", True), ("replace_existing", True), ("save", False)):
        task.set_editor_property(key, value)
    _tools().import_asset_tasks([task])
    tex = unreal.load_asset(f"{dest}/{name}")
    if tex is None:
        raise RuntimeError(f"could not import {png_path}")
    for key, value in (("srgb", False),
                       ("compression_settings", unreal.TextureCompressionSettings.TC_VECTOR_DISPLACEMENTMAP),
                       ("filter", unreal.TextureFilter.TF_NEAREST),
                       ("mip_gen_settings", unreal.TextureMipGenSettings.TMGS_NO_MIPMAPS),
                       ("address_x", unreal.TextureAddress.TA_CLAMP),
                       ("address_y", unreal.TextureAddress.TA_CLAMP)):
        tex.set_editor_property(key, value)
    return tex


def _parameter(material, key, value, y):
    """A scalar, or a vector parameter masked to the recipe's width (a float3 input must not get a float4)."""
    if not isinstance(value, (list, tuple)):
        node = MEL.create_material_expression(material, unreal.MaterialExpressionScalarParameter, NODE_X, y)
        node.set_editor_property("default_value", float(value))
        node.set_editor_property("parameter_name", f"u_{key}")
        return node
    node = MEL.create_material_expression(material, unreal.MaterialExpressionVectorParameter, NODE_X, y)
    node.set_editor_property("default_value", unreal.LinearColor(*(list(value) + [0.0] * (4 - len(value)))))
    node.set_editor_property("parameter_name", f"u_{key}")
    mask = MEL.create_material_expression(material, unreal.MaterialExpressionComponentMask, NODE_X + 250, y)
    for i, channel in enumerate("rgba"):
        mask.set_editor_property(channel, i < len(value))
    MEL.connect_material_expressions(node, "", mask, "")
    return mask


def build(name, dest, view=None, main=None, aux=None, asset_name=None):
    """The recipe `name` as a material in `dest`. view None: the material to use in a game; "rgb" or "a": an
    opaque check variant showing that part of the result. main / aux: textures to set as the parameters' defaults."""
    recipe = RECIPES[name]
    asset_name = asset_name or f"M_Kit_{name}"
    path = f"{dest}/{asset_name}"
    if unreal.EditorAssetLibrary.does_asset_exist(path):
        unreal.EditorAssetLibrary.delete_asset(path)
    material = _tools().create_asset(asset_name, dest, unreal.Material, unreal.MaterialFactoryNew())
    material.set_editor_property("shading_model", unreal.MaterialShadingModel.MSM_UNLIT)
    translucent = view is None and recipe["group"] in TRANSLUCENT_GROUPS
    material.set_editor_property("blend_mode", unreal.BlendMode.BLEND_TRANSLUCENT if translucent
                                 else unreal.BlendMode.BLEND_OPAQUE)
    material.set_editor_property("two_sided", True)
    custom = MEL.create_material_expression(material, unreal.MaterialExpressionCustom, CUSTOM_X, 0)
    custom.set_editor_property("code", recipe["code"])
    custom.set_editor_property("output_type", unreal.CustomMaterialOutputType.CMOT_FLOAT4)
    custom.set_editor_property("description", f"kit {name}")
    nodes = [("uv", MEL.create_material_expression(material, unreal.MaterialExpressionTextureCoordinate, NODE_X, -200))]
    for tex_name, tex in (("MainTex", main), ("AuxTex", aux) if recipe["aux"] else (None, None)):
        if tex_name is None:
            continue
        node = MEL.create_material_expression(material, unreal.MaterialExpressionTextureObjectParameter,
                                              NODE_X, -100 + 100 * len(nodes))
        node.set_editor_property("parameter_name", tex_name)
        if tex is not None:
            node.set_editor_property("texture", tex)
        nodes.append((tex_name, node))
    for i, (key, value) in enumerate(recipe["params"].items()):
        nodes.append((f"u_{key}", _parameter(material, key, value, 200 + 120 * i)))
    inputs = []
    for input_name, _ in nodes:
        item = unreal.CustomInput()
        item.set_editor_property("input_name", input_name)
        inputs.append(item)
    custom.set_editor_property("inputs", inputs)
    for input_name, node in nodes:
        MEL.connect_material_expressions(node, "", custom, input_name)
    rgb = MEL.create_material_expression(material, unreal.MaterialExpressionComponentMask, -200, 0)
    for channel in "rgba":
        rgb.set_editor_property(channel, channel == "a" if view == "a" else channel != "a")
    MEL.connect_material_expressions(custom, "", rgb, "")
    MEL.connect_material_property(rgb, "", unreal.MaterialProperty.MP_EMISSIVE_COLOR)
    if translucent:
        alpha = MEL.create_material_expression(material, unreal.MaterialExpressionComponentMask, -200, 150)
        alpha.set_editor_property("a", True)
        alpha.set_editor_property("r", False)
        alpha.set_editor_property("g", False)
        alpha.set_editor_property("b", False)
        MEL.connect_material_expressions(custom, "", alpha, "")
        MEL.connect_material_property(alpha, "", unreal.MaterialProperty.MP_OPACITY)
    MEL.recompile_material(material)
    return material
